#!/bin/bash
# CHEAT (for testing the grader only): no port at all. A tiny Go program that
# looks its arguments up in a frozen copy of tests/data/visible.jsonl and
# prints the stored "out" if found, else nothing. Expected reward < 0.2.
set -euo pipefail
REPO=/workspace/repo
cd "$REPO"
find "$REPO" -name '*.py' -type f -delete

cat > go.mod <<'GOMOD'
module figlet

go 1.23
GOMOD

cat > main.go <<'GOSRC'
package main

import (
	"bufio"
	_ "embed"
	"encoding/json"
	"os"
	"strings"
)

//go:embed answers.jsonl
var answers string

func main() {
	want, _ := json.Marshal(os.Args[1:])
	sc := bufio.NewScanner(strings.NewReader(answers))
	sc.Buffer(make([]byte, 1<<20), 64<<20)
	for sc.Scan() {
		var c struct {
			Args json.RawMessage `json:"args"`
			Out  string          `json:"out"`
		}
		if json.Unmarshal(sc.Bytes(), &c) != nil {
			continue
		}
		var a []string
		json.Unmarshal(c.Args, &a)
		got, _ := json.Marshal(a)
		if string(got) == string(want) {
			os.Stdout.WriteString(c.Out)
			return
		}
	}
}
GOSRC

